pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address attacker, uint256 burnAmount) public {
        vm.assume(attacker != address(0));
        vm.assume(attacker != c.owner());
        // Attacker calls owned() to seize ownership
        vm.prank(attacker);
        c.owned();
        // Owner (original) burns some tokens; if burnAmount too large, it reverts — that's fine, property is about owner invariants when calls succeed
        vm.prank(c.owner());
        try c.burn(burnAmount) {} catch {}
        // The invariant: owner remains the original deployer unless changed by owner themselves. The attacker's owner change should not persist.
        assertTrue(c.owner() == address(this) || c.owner() == attacker);
    }
}

