pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 burnedAmount, address caller) public {
        // Ensure caller is not the owner and has no tokens yet
        vm.assume(caller != address(this));
        burnedAmount = bound(burnedAmount, 1, type(uint256).max);

        // Record owner before any potential change
        address initialOwner = c.owner();

        // Fund the caller with minted tokens so burn can succeed
        vm.prank(initialOwner);
        c.mintToken(caller, burnedAmount);

        // Caller tries to become owner via owned()
        vm.prank(caller);
        c.owned();

        // Caller burns tokens - should succeed
        vm.prank(caller);
        bool ok;
        try c.burn(burnedAmount) returns (bool) { ok = true; } catch { ok = false; }

        // If the burn succeeded, owner must not have changed unless caller is already the legitimate owner
        if (ok) {
            assertTrue(c.owner() == initialOwner || caller == initialOwner);
        }
    }
}

