import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 burnAmount) public {
        // 1. Keep domain wide; restrict caller not to be the zero address
        vm.assume(caller != address(0));
        // 2. Setup: owner mints some tokens to caller so they have a balance to burn
        address owner = address(this);
        // The constructor sets the deployer as owner with initialSupply=0;
        // we need totalSupply > 0 to observe a change, so mint tokens.
        vm.prank(owner);
        c.mintToken(caller, 1000);
        // Ensure burnAmount does not exceed caller's balance to avoid reverting in burn's internal require
        vm.assume(burnAmount > 0 && burnAmount <= c.balanceOf(caller));
        // Record totalSupply before the burn attempt by caller
        uint256 supplyBefore = c.totalSupply();
        // caller attempts to burn
        vm.prank(caller);
        try c.burn(burnAmount) { } catch { }
        uint256 supplyAfter = c.totalSupply();
        // 3. Assertion: totalSupply should remain unchanged when a non-owner calls burn,
        // because the non-owner cannot satisfy the ownership modifier.
        // The mutant bypasses the ownership check, so totalSupply would decrease.
        assertTrue(supplyAfter == supplyBefore);
    }
}

