pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address nonOwner, uint256 burnAmount) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(this));
        vm.assume(burnAmount <= type(uint256).max);

        // Give nonOwner some tokens to burn
        vm.prank(address(c).balance == 0 ? address(0) : address(0)); // just ensure prank
        c.mintToken(nonOwner, burnAmount);

        // nonOwner tries to freeze themselves
        vm.prank(nonOwner);
        c.freezeAccount(nonOwner, true);

        // nonOwner tries to burn
        vm.prank(nonOwner);
        bool success;
        try c.burn(burnAmount) returns (bool r) {
            success = r;
        } catch {
            success = false;
        }

        // The reference onlyOwner modifier prevents nonOwner from freezing, so burn always succeeds when balance is sufficient.
        // The mutant allows anyone to freeze, so nonOwner can freeze themselves, causing burn to revert.
        // Thus, in the reference, success is true; in mutant, success is false for some input.
        assertTrue(success);
    }
}

