pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(100, "Test", "TST");
    }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(this));
        amount = bound(amount, 0, c.balanceOf(address(this)));

        // Actor freezes themselves (only succeeds or is callable in both, but effect differs)
        vm.prank(actor);
        c.freezeAccount(actor, true);

        // Actor attempts to burn their own tokens
        vm.prank(actor);
        bool ok;
        try c.burn(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: non-owner cannot freeze, so actor is not frozen and burn succeeds if they have balance.
        // Mutant: anyone can freeze, actor freezes themselves, burn reverts due to frozen account.
        // Therefore the reference never reverts (ok == true) when balance >= amount,
        // while the mutant reverts (ok == false) for some input.
        assertTrue(ok);
    }
}

