contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 burnAmount) public {
        // Admissible: burn amount must not exceed total supply (initial supply = 0, so totalSupply = 0).
        // Since initialSupply=0, totalSupply=0, balanceOf[msg.sender]=0, only burn(0) is admissible.
