    constructor(C _c) {
        c = _c;
    }
    function testBurnBalanceRule(address burner, uint256 burnAmount, uint256 initialBalance) public {
        require(burnAmount > 0);
        require(initialBalance >= burnAmount);
        // Set the burner's balance to initialBalance via mintToken (caller must be owner for mint to succeed).
        // We assume the test contract is the owner; if not, the mint will revert and the test stops.
        c.mintToken(burner, initialBalance);
        // Record balance before burn
        uint256 balBefore = c.balanceOf(burner);
        // Attempt the burn as the owner (this contract is owner).
        // The burn function does not use msg.sender to deduct balance, it deducts from owner (this contract).
        // To test the burner's balance, the burner must be the owner, so we set burner = address(this).
        // Actually, to isolate the burn effect, we transfer enough tokens to the burner and then make them owner? Not possible.
        // The burn function deducts from the owner (msg.sender), not the burner. So we need to make the burner the owner.
        // But we can only interact via c. We'll call c.burn(burnAmount) as the test contract (owner), which modifies owner balance.
        // Scenario: Use transfer to move tokens to another address, then check that after burn, totalSupply and owner balance decreased correctly.
        // Actually, to check the rule, we burn from the owner.
        // Record balance of owner before burn
        address ownerAddr = c.owner();
        uint256 ownerBalBefore = c.balanceOf(ownerAddr);
        // The burn call
        bool success = c.burn(burnAmount);
        // Read owner balance after
        uint256 ownerBalAfter = c.balanceOf(ownerAddr);
        // Read totalSupply after
        uint256 supplyAfter = c.totalSupply();
        // Read totalSupply before? We can't read totalSupply before the call without a view call, but we can compute expected supply after from initial minted amounts.
        // Instead, a simpler rule: owner's balance after burn plus burnAmount equals owner's balance before burn and no revert.
        // But the mutant allows underflow, so if burnAmount > ownerBalBefore, balanceOf[msg.sender] underflows and totalSupply decreases.
        // The general rule: if burn returns true and no revert, then ownerBalAfter == ownerBalBefore - burnAmount.
        // In C, require ensures ownerBalBefore >= burnAmount, so this holds. In M, if ownerBalBefore < burnAmount, balanceOf underflows, ownerBalAfter = 2^256-1 - (burnAmount - ownerBalBefore) + 1? => huge number, not equal to expected difference.
        assert(!success || (ownerBalAfter == ownerBalBefore - burnAmount));
    }
}

