        bound(burnAmount, 1, type(uint128).max);

        // The owner mints tokens to themselves and then burns
        vm.prank(c.owner());
        c.mintToken(c.owner(), mintAmount);
        vm.prank(c.owner());
        c.burn(burnAmount);

        // Assert that the owner's balance is not greater than totalSupply
        // In the correct contract, burn reduces balance and totalSupply equally, so balance <= totalSupply always holds.
        // In the buggy contract, balance can underflow, making it > totalSupply (wraps to a huge number).
        assertTrue(c.balanceOf(c.owner()) <= c.totalSupply());
    }
}

