pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 burnAmount) public {
        // Restrict burnAmount to a reasonable range to avoid overflow in preconditions
        bound(burnAmount, 1, type(uint256).max / 2);
        // Owner is the deployer (this test contract). Give the owner some initial balance via mint
        address owner = address(this);
        vm.prank(owner);
        c.mintToken(owner, burnAmount);
        // Record balance before burn
        uint256 balanceBefore = c.balanceOf(owner);
        // Execute burn as owner
        vm.prank(owner);
        c.burn(burnAmount);
        // After burn, the caller's balance must have decreased
        uint256 balanceAfter = c.balanceOf(owner);
        assertTrue(balanceAfter <= balanceBefore);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address a, address b, uint256 amt) public returns (bool) {
        require(a != b);
        uint256 supplyBefore = c.totalSupply();
        uint256 balA = c.balanceOf(a);
        uint256 balB = c.balanceOf(b);
        c.mintToken(a, amt);
        c.transfer(b, amt);
        c.transfer(a, amt);
        assert(c.totalSupply() == balA + balB + 2 * amt);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public payable {
        require(true);
        c.owned();
        uint256 supplyBefore = c.totalSupply();
        uint256 ownerBalBefore = c.balanceOf(address(this));
        bool reverted; try c.burn(burnAmount) { reverted = false; } catch { reverted = true; }
        uint256 supplyAfter = c.totalSupply();
        uint256 ownerBalAfter = c.balanceOf(address(this));
        assert(!reverted ? (supplyAfter == supplyBefore - burnAmount && ownerBalAfter == ownerBalBefore - burnAmount) : true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
